// Sessions of Part I (fall) and Part II (winter).
// The recordings describe the work in the third person. The game puts no invented words in a real person's mouth.
// plate: [names shown, work, year, where]. ev: the evidence card, written from the case data. sus: [suspect, change].
const p = (v, d = 0) => (v * 100).toFixed(d) + '%', n = (v) => Math.round(v).toLocaleString('en-US');
const S = (id, core, place, plate, credited, lines, qa, covers, ev, sus, slot, talk, wren, src) => ({ id, part: id.startsWith('II-') ? 2 : 1, core, place, plate, credited, lines, qa, covers, ev, sus, slot, talk, wren, src });

export const PART1 = [
  S('I-1', true, 'deckle', ['Ines Varga, head librarian', 'The loan log of the Common Shelf', 'this year', 'the Stacks, Deckle'], [],
    ['Ines Varga runs the Common Shelf. She has an annual report with two facts in it that she cannot make agree.', 'Marginalia, the screen that suggests five books to each reader, is right more often every year. And every year the readers borrow a narrower set of books.', 'She asks you to start where every analysis starts: with what is in the table, and what kind of thing each column holds.'],
    ['She wants to know whether readers’ tastes narrowed, or whether the engine narrowed them.', 'A column can be missing without anyone noticing, because a table never lists what it does not contain.', 'Every later session ends with one card of evidence from this library.'],
    ['Data and information', 'The five V’s', 'Nominal, ordinal, interval and ratio data', 'Missing data'],
    (C) => `The loan log has four columns: reader, title, date, branch. There is a fifth with no header. Nobody at the Stacks recalls what it was for.`, [], 'collect',
    'Is a postcode a number? Could you take its average?', 'If a box in the table is empty, how do you know whether it was zero or nobody wrote it down?', ['The Common Shelf, Deckle and everyone in them are invented for this game.']),
  S('I-2', true, 'yale', ['Frank Anscombe', '“Graphs in Statistical Analysis”', '1973', 'Yale University'], [],
    ['In 1973 Frank Anscombe, a statistician at Yale, published four small tables of numbers.', 'Each table has the same averages, the same spread and the same correlation.', 'Drawn as pictures they could not be more different: a cloud, a curve, a line with one stray point, and a column with one point far away.'],
    ['He wanted people to stop trusting a printout they had not plotted. Computers had made summaries cheap.', 'One number can describe a line, a curve and a single wild point equally well.', 'The four tables are still among the first things a statistics course shows.'],
    ['Covariance', 'Correlation', 'Plot before you summarize'],
    (C) => `Total loans per month are flat across six years: about ${n(C.y.loans[0])} then, about ${n(C.y.loans[5])} now. How unevenly they fall across titles is not flat. That measure rose from ${C.y.gini[0].toFixed(2)} to ${C.y.gini[5].toFixed(2)}.`, [[1, -1]], 'describe',
    'Ice-cream sales and sunburn rise together. Does one cause the other?', 'How can four different pictures have the same numbers?', ['Anscombe, F. J. (1973). Graphs in Statistical Analysis. The American Statistician, 27(1).']),
  S('I-3', false, 'yale', ['Edward Tufte', 'The Visual Display of Quantitative Information', '1983', 'Yale University'], [],
    ['Edward Tufte taught statistics and political science at Yale.', 'He published his book on charts himself in 1983, so that it could be printed the way he wanted.', 'It argues that a chart should spend its ink on the data, and that the picture should change exactly as much as the numbers do.'],
    ['He was collecting the best and worst charts ever printed and asking what set them apart.', 'An axis that starts halfway up makes a small change look enormous.', 'His “lie factor” is still a quick test for any chart in a report.'],
    ['Data-ink ratio', 'Chartjunk', 'Lie factor', 'Choosing a chart for the question', 'Playfair, Minard and Nightingale'],
    (C) => `The board’s yearly chart cut its axis and showed accuracy alone. Redrawn from zero, beside breadth: the hit rate goes from ${p(C.y.hit[0])} to ${p(C.y.hit[5])} while different titles borrowed per month go from ${n(C.y.distinct[0])} to ${n(C.y.distinct[5])}.`, [[4, -1]], 'describe',
    'Find a chart at home, on a cereal box or in a newspaper. Does it start at zero?', 'Why would anyone draw a chart that makes a small change look big?', ['Tufte, E. R. (1983). The Visual Display of Quantitative Information. Graphics Press.']),
  S('I-4', true, 'princeton', ['John Tukey', 'Exploratory Data Analysis', '1977', 'Princeton University'], [],
    ['John Tukey divided his working week between Princeton and Bell Labs.', 'His 1977 book teaches a habit: look at the data with simple pictures before you test anything.', 'The boxplot and the stem-and-leaf display come from it.'],
    ['He thought statistics spent too long confirming ideas and too little time finding them.', 'One very large value drags the average, and the average then describes nobody.', 'A boxplot is still the quickest way to compare many groups at a glance.'],
    ['Mean, median and mode', 'Variance and standard deviation', 'Boxplot', 'Histogram and density', 'Skew'],
    (C) => `Half of all titles were borrowed ${C.titles.medianLast} times or fewer last year, and ${p(C.titles.zeroLast)} were not borrowed at all. In the first year ${p(C.titles.zeroFirst)} went unborrowed. By now ${p(C.y.offsite[5])} of the collection is in off-site storage.`, [[2, 1]], 'describe',
    'In your family, who is the “median” by age? Is that different from the average age?', 'If one person reads a hundred books, does that mean everyone reads a lot?', ['Tukey, J. W. (1977). Exploratory Data Analysis. Addison-Wesley.']),
  S('I-5', true, 'google', ['Sanjay Ghemawat', 'MapReduce', '2004', 'Google'], ['Jeffrey Dean'],
    ['In 2004 Jeffrey Dean and Sanjay Ghemawat described how Google counted things across thousands of ordinary computers.', 'A programmer writes two small functions, map and reduce. The system splits the work, hands it out and gathers the results.', 'With thousands of machines something is always broken or slow, so the system quietly reruns the parts that lag.'],
    ['They wanted engineers to process huge files without each one rewriting the same plumbing.', 'One slow machine can hold up the whole job unless its work is given to another.', 'The same split, work, gather pattern runs through most large data systems.'],
    ['Big data', 'Structured data', 'Which data are worth keeping'],
    (C) => `Six years of loans fit in a small file, so the library kept them. A record of every screen Marginalia showed was far larger, and was deleted after ${C.planted.screenLogDays} days.`, [], 'collect',
    'What would you keep if you could only store one notebook a year about your household?', 'If the library threw the screen records away, how could anyone check what the screens did?', ['Dean, J., & Ghemawat, S. (2004). MapReduce: Simplified Data Processing on Large Clusters. OSDI.']),
  S('I-6', true, 'harvard', ['Donald Rubin', 'Potential outcomes', '1974', 'recorded at Harvard University'], [],
    ['Donald Rubin’s 1974 paper asks what “the effect of a treatment” means.', 'For each person there are two outcomes: one with the treatment and one without. We only ever see one of them.', 'So a question about cause is a question about missing data, and a fair coin is the way to fill the gap correctly on average.'],
    ['He wanted one language for experiments and for studies where nobody ran an experiment.', 'When people choose their own treatment, the two groups differ before anything is done to them.', 'Drug trials, school studies and website tests are all described in these terms.'],
    ['Counterfactuals', 'The fundamental problem of causal inference', 'Average treatment effect', 'Randomization', 'Causal inference as missing data'],
    (C) => `Each loan shows one outcome: the book that was taken. The log does not say whether the reader was shown that book first. Arms known for the sample you checked: 0 of 12.`, [[5, 1]], 'explain',
    'Think of a choice you made today. What would have happened otherwise? How could you ever find out?', 'Why can’t you just ask people what they would have done?', ['Rubin, D. B. (1974). Estimating causal effects of treatments in randomized and nonrandomized studies. Journal of Educational Psychology, 66(5).']),
  S('I-7', true, 'mit', ['Joshua Angrist', 'The draft lottery study', '1990', 'MIT'], [],
    ['Does army service change what people earn later? Volunteers differ from everyone else, so comparing them settles nothing.', 'In the early 1970s the United States called men up by a lottery of birthdays. Joshua Angrist used those draws in a study published in 1990.', 'A lottery does not look at who you are, so the men with low numbers and high numbers were alike in everything else.'],
    ['He needed two groups that differed only in the thing being studied.', 'Leave out a cause that moves both columns and a regression can point the wrong way.', 'Economists now look for such accidents everywhere: a birthday cut-off, a border, a broken machine.'],
    ['Selection bias', 'Omitted variable bias', 'Simultaneity', 'Natural experiments'],
    (C) => `For ${C.outage.days} days in year five an outage switched Marginalia off at ${C.outage.branch}. That month its readers borrowed ${n(C.outage.distinctDuring)} different titles, against ${n(C.outage.distinctBefore)} in a usual month, from about the same number of loans. The month after, it was back to ${n(C.outage.distinctAfter)}.`, [[5, 2], [1, -1]], 'explain',
    'Has an accident ever shown you something a plan could not? A power cut, a snow day?', 'Why is a broken computer better evidence than asking readers what they like?', ['Angrist, J. D. (1990). Lifetime Earnings and the Vietnam Era Draft Lottery. American Economic Review, 80(3).']),
  S('I-8', true, 'illinois', ['Jiawei Han', 'Data Mining: Concepts and Techniques', 'first edition around 2000', 'University of Illinois'], ['Micheline Kamber', 'Jian Pei'],
    ['Jiawei Han’s textbook gave a young field a shared vocabulary.', 'Its chapters on frequent patterns begin in a shop: which items land in the same basket?', 'Three measures do the work. Support says how common a set is, confidence how often the rule holds, and lift whether it beats chance.'],
    ['Shops had started keeping every receipt and wanted to know what the receipts could tell them.', 'A rule can be right nine times in ten simply because nearly everyone buys the second item anyway.', 'The same counts sit behind “often bought together”.'],
    ['Itemsets', 'Support, confidence and lift', 'Maximal and closed itemsets'],
    (C) => `The nightly job only counts titles borrowed by at least 2% of readers. ${C.support.titlesCan} titles pass. That is ${p(C.support.share, 1)} of the catalogue. No other book can ever appear in a rule.`, [[5, 1]], 'model',
    'Which two things in your kitchen are always used together? Which only seem to be?', 'If nearly everyone buys bread, is “tea, so bread” a real pattern?', ['Han, J., Kamber, M., & Pei, J. (2011). Data Mining: Concepts and Techniques (3rd ed.). Morgan Kaufmann.']),
  S('I-9', false, 'ibm', ['Rakesh Agrawal and Ramakrishnan Srikant', 'Apriori', '1994', 'recorded at IBM Almaden'], [],
    ['Counting every possible combination of items in a shop is hopeless: there are too many.', 'Rakesh Agrawal and Ramakrishnan Srikant, at IBM’s Almaden lab in 1994, used one observation. A set cannot be common unless every part of it is common.', 'So a program can count small sets first and never look at anything built on a rare one.'],
    ['They needed association rules fast enough for real shop data.', 'Set the bar low and almost nothing is pruned, so the counting never ends.', 'Level-by-level search with pruning is a pattern that turns up all over computing.'],
    ['Candidate generation', 'The Apriori principle', 'AprioriTid'],
    (C) => `Marginalia’s nightly job prunes rare titles first. That is what makes it fast enough to finish before the Stacks opens.`, [[5, 1]], 'model',
    'If hardly anyone owns a unicycle, how many people own a unicycle and a tuba?', 'Is it cheating to skip counting things?', ['Agrawal, R., & Srikant, R. (1994). Fast Algorithms for Mining Association Rules. VLDB.']),
  S('I-10', false, 'rensselaer', ['Mohammed Zaki', 'Eclat', '2000', 'Rensselaer Polytechnic Institute'], ['Srinivasan Parthasarathy', 'Mitsunori Ogihara', 'Wei Li'],
    ['Mohammed Zaki turned the table on its side.', 'Instead of listing the items in each basket, list the baskets for each item.', 'The support of a pair is then simply how many baskets the two lists share.'],
    ['He wanted to mine patterns without rereading the whole database again and again.', 'For very common items the lists are long and comparing them is slow.', 'Storing data by column is now ordinary in analytics databases.'],
    ['Vertical data format', 'Intersecting transaction lists'],
    (C) => `Rare titles have short lists, so they are the cheapest of all to count. Leaving them out of the nightly job was a choice about what mattered.`, [[2, -1]], 'model',
    'Is it quicker to list the friends at each party, or the parties each friend went to?', 'If rare books are cheap to count, why skip them?', ['Zaki, M. J. (2000). Scalable Algorithms for Association Mining. IEEE Transactions on Knowledge and Data Engineering, 12(3).']),
  S('I-11', true, 'amazon', ['Greg Linden, Brent Smith and Jeremy York', 'Item-to-item collaborative filtering', '2003', 'Amazon'], [],
    ['With millions of customers, comparing every customer to every other was too slow to do while a page loaded.', 'Greg Linden, Brent Smith and Jeremy York compared items instead: which things are bought by the same people?', 'The table of similar items is built ahead of time, so a suggestion is a quick lookup.'],
    ['They needed suggestions in a fraction of a second, for a catalogue of millions.', 'A bestseller is bought by everyone, so it looks similar to everything.', 'Most “people who liked this” lists descend from this design.'],
    ['Uses of frequent patterns', 'Recommender systems', 'Similarity'],
    (C) => `Marginalia 1 worked this way for its first two years. Titles that were already popular were shown more, and what was shown was borrowed more: the hundred most-borrowed titles went from ${p(C.m.top100[0])} of loans to ${p(C.m.top100[23])}.`, [[5, 1]], 'model',
    'When a friend recommends a film, do they pick what you would like or what everyone likes?', 'If the screen shows a book to everyone, is it popular because it is good?', ['Linden, G., Smith, B., & York, J. (2003). Amazon.com Recommendations: Item-to-Item Collaborative Filtering. IEEE Internet Computing, 7(1).']),
  S('I-12', false, 'gottingen', ['Carl Friedrich Gauss', 'The method of least squares', '1809', 'Göttingen'], [],
    ['On New Year’s Day 1801 the astronomer Giuseppe Piazzi found a small new object, Ceres, and soon lost it in the Sun’s glare.', 'Carl Friedrich Gauss, aged twenty-four, calculated where it would reappear. At the end of the year it was found close to where he said.', 'He published his method of least squares in 1809. Adrien-Marie Legendre had printed the same idea in 1805, and the two disagreed about who had it first.'],
    ['He had a handful of imperfect sightings and needed the orbit that fitted them best.', 'A line fitted to a short stretch can be wildly wrong far outside it.', 'Least squares is still the default way to fit a line to points.'],
    ['Least-squares line', 'Residuals', 'R-squared and adjusted R-squared', 'Controls and bad controls', 'Extrapolation'],
    (C) => `A straight line from last year’s loans predicts this year’s loans for each title very well (R² = ${C.regression.r2}). It says that popular books stay popular. It does not say why.`, [[4, -1]], 'model',
    'If a child grew 6 cm a year from age 5 to 10, how tall will they be at 40?', 'Why squares? Why not just add up the misses?', ['Gauss, C. F. (1809). Theoria motus corporum coelestium. Perthes and Besser.']),
  S('I-13', true, 'maryland', ['Galit Shmueli', '“To Explain or to Predict?”', '2010', 'recorded at the University of Maryland'], [],
    ['Galit Shmueli’s 2010 paper says that explaining and predicting are different jobs.', 'A model can predict well and explain nothing. Another can explain well and predict poorly.', 'Trouble starts when a model built for one job is trusted with the other.'],
    ['She saw whole fields use one kind of model and judge it by the standards of the other.', 'When a measure is made into a target, people and machines learn to hit the measure.', 'Asking “describe, predict or explain?” is a good first question for any analysis.'],
    ['Descriptive, predictive and explanatory models', 'Study design', 'Data collection'],
    (C) => `The board asked whether Marginalia is good for readers. It was answered with a prediction score: ${p(C.y.hit[5])}. In the same years the readers’ own survey score went from ${C.y.survey[0].toFixed(2)} to ${C.y.survey[5].toFixed(2)}.`, [[4, -1]], 'explain',
    'A thermometer predicts whether people wear coats. Does it explain why?', 'Can a guess be right for the wrong reason?', ['Shmueli, G. (2010). To Explain or to Predict? Statistical Science, 25(3).']),
  S('I-14', false, 'edinburgh', ['Thomas Bayes', 'An Essay towards solving a Problem in the Doctrine of Chances', '1763', 'Edinburgh'], [],
    ['Thomas Bayes was a minister who had studied at Edinburgh. When he died in 1761 he left an essay unpublished.', 'His friend Richard Price edited it and sent it to the Royal Society, which printed it in its transactions for 1763.', 'It asks how to reason backward: from what you have seen, to how likely each explanation is.'],
    ['He wanted to say how sure you can be about a chance after watching it play out a few times.', 'With little evidence, your starting belief decides the answer.', 'Spam filters, medical tests and weather forecasts all update beliefs this way.'],
    ['Prior, likelihood and posterior', 'Maximum likelihood', 'Maximum a posteriori', 'Naive Bayes'],
    (C) => `A new reader with two loans is treated like the average reader, and the average reader borrows bestsellers. Their first screens are the five most-borrowed titles.`, [[5, 1]], 'model',
    'You hear hooves outside. Horse or zebra? What would change your mind?', 'How many times do you have to see something before you believe it?', ['Bayes, T. (1763). An Essay towards solving a Problem in the Doctrine of Chances. Philosophical Transactions of the Royal Society, 53.']),
  S('I-15', false, 'wisconsin', ['George Box and David Cox', '“An Analysis of Transformations”', '1964', 'University of Wisconsin'], [],
    ['Many methods work best on data that are roughly bell-shaped, and real data seldom are.', 'George Box and David Cox proposed a family of power transformations with one dial, and a way to let the data choose its setting.', 'The story goes that they decided to write something together partly because their names rhymed.'],
    ['They wanted a principled way to pick a transformation instead of trying a few by eye.', 'Tidying has side effects. Merging small categories erases exactly the unusual cases.', 'Taking a logarithm of money, counts or sizes is still the first thing to try.'],
    ['Binarization and binning', 'Log and power transforms', 'Scaling', 'Interaction features', 'One-hot, dummy and effect coding', 'Rare categories'],
    (C) => `Before modelling, every subject with under 1% of loans was merged into “Other”. ${C.subjects.under1} of the ${C.subjects.total} subjects became one. Together they held ${p(C.subjects.under1Share)} of last year’s loans.`, [[5, 1]], 'engineer',
    'If you sorted your books into five boxes, what would end up in the box marked “other”?', 'What gets lost when you tidy up?', ['Box, G. E. P., & Cox, D. R. (1964). An Analysis of Transformations. Journal of the Royal Statistical Society B, 26(2).']),
  S('I-16', false, 'belllabs', ['Stuart Lloyd', 'Least-squares quantization', '1957', 'Bell Labs'], [],
    ['Stuart Lloyd wrote up his method in 1957 as a Bell Labs note about sending signals with few bits.', 'Choose some levels. Assign each sample to its nearest level. Move each level to the middle of its samples. Repeat.', 'The note was not formally published until 1982. By then others had found the same idea, and it had been named k-means.'],
    ['He wanted to describe a signal with a handful of levels and lose as little as possible.', 'The method likes round, equal groups, and will invent them if they are not there.', 'It compresses pictures, groups customers and starts off many other methods.'],
    ['k-means', 'Initialization', 'Limits with size, density and shape', 'Vector quantization'],
    (C) => `Marginalia 2 put every reader into one of ${C.planted.clusters} clusters and showed each cluster its own top titles. A reader with an unusual mix was served as the nearest cluster.`, [[5, 1]], 'model',
    'Sort the cutlery drawer into three groups. Would everyone at home pick the same three?', 'What if someone belongs in two groups?', ['Lloyd, S. P. (1982). Least squares quantization in PCM. IEEE Transactions on Information Theory, 28(2). Written in 1957.']),
  S('I-17', false, 'stanford', ['David Arthur and Sergei Vassilvitskii', 'k-means++', '2007', 'Stanford University'], [],
    ['k-means can end somewhere poor if its starting points are unlucky.', 'David Arthur and Sergei Vassilvitskii proposed in 2007 to choose each new starting point at random, but favouring points far from those already chosen.', 'They proved that this start is, on average, within a known factor of the best possible.'],
    ['They wanted a start that was nearly as cheap as picking at random and reliably better.', 'The method needs to be told how many groups to find, and the data do not always say.', 'It is the default start in most software.'],
    ['k-means++ seeding', 'Choosing k', 'Compactness and separation', 'Silhouette and Calinski-Harabasz indices'],
    (C) => `In year one, readers fell into clear groups by what they read: silhouette ${C.k.silFirst[C.k.first - 2].toFixed(2)} at k = ${C.k.first}. In year six no number of groups fits well. The best is ${Math.max(...C.k.silLast).toFixed(2)}. The groups have run together.`, [[5, 1]], 'model',
    'How many kinds of weather are there? Who decides?', 'How do you know how many groups there really are?', ['Arthur, D., & Vassilvitskii, S. (2007). k-means++: The Advantages of Careful Seeding. SODA.']),
  S('I-18', false, 'munich', ['Martin Ester, Hans-Peter Kriegel, Jörg Sander and Xiaowei Xu', 'DBSCAN', '1996', 'University of Munich'], [],
    ['Clusters on a map are rarely round. A river town is a long thin shape.', 'Four researchers in Munich defined a cluster in 1996 as a region where points are packed densely, whatever its outline.', 'Points in thin regions belong to no cluster. The method calls them noise.'],
    ['They were working with map data, where clusters follow coasts and roads.', 'One setting for “dense” cannot suit a crowded region and a sparse one at once.', 'It is used wherever shapes are irregular: maps, sensor readings, astronomy.'],
    ['Core, border and noise points', 'Eps and MinPts', 'OPTICS'],
    (C) => `Readers whose main subject is a rare one were ${p(C.noise.rareMainFirst)} of readers in year one and are ${p(C.noise.rareMain)} now. To a density method they are scattered points, and scattered points get the default list.`, [[5, 1]], 'model',
    'In a playground, who counts as “in a group” and who is on their own? How near is near?', 'Is it fair to call someone noise?', ['Ester, M., Kriegel, H.-P., Sander, J., & Xu, X. (1996). A Density-Based Algorithm for Discovering Clusters in Large Spatial Databases with Noise. KDD.']),
  S('I-19', false, 'eth', ['Paul Jaccard', 'The coefficient of community', '1901', 'recorded at ETH Zurich'], [],
    ['Paul Jaccard was a botanist comparing alpine meadows. Which two meadows are most alike?', 'In 1901 he counted the species two meadows share and divided by the species found in either.', 'The same ratio now compares documents, shopping baskets and readers.'],
    ['He needed a fair comparison between a meadow with many species and one with few.', 'Every way of measuring distance quietly decides what counts as the same.', 'Choosing the distance is often the most important choice in a clustering.'],
    ['Metric properties', 'Manhattan, Euclidean and Minkowski distance', 'Cosine, Hamming and Jaccard', 'Distance between strings', 'k-nearest neighbours'],
    (C) => `Measured by straight-line distance on raw loan counts, every light reader sits in one tight clump near zero. Their tastes differ. The ruler cannot see it.`, [], 'engineer',
    'Which two people in your family are most alike? Alike in what?', 'Can two things be close one way and far another way?', ['Jaccard, P. (1901). Étude comparative de la distribution florale dans une portion des Alpes et du Jura. Bulletin de la Société Vaudoise des Sciences Naturelles, 37.']),
  S('I-20', false, 'belllabs', ['Ken Thompson', 'Regular expression search', '1968', 'Bell Labs'], [],
    ['A regular expression is a compact way to describe a pattern of characters.', 'Ken Thompson’s 1968 paper showed how to turn one into a small machine that reads text once, keeping track of every way the pattern could still match.', 'He built it into his text editors, and from there it spread to almost every programming tool.'],
    ['He wanted searching by pattern to be fast enough to use while editing.', 'A pattern that is a little too strict silently drops real records.', 'Cleaning messy text almost always starts with patterns like these.'],
    ['The text pipeline', 'Data cleaning', 'Regular expressions'],
    (C) => `For four months in year four, a system migration logged renewals twice at ${C.migration.branches.join(' and ')}: ${n(C.migration.extra)} loans that never happened, ${p(C.migration.extraShare, 1)} of those months. Taking them out barely moves any yearly figure.`, [[3, 1]], 'clean',
    'Write a rule for a car number plate in your country. Does every real plate pass?', 'What happens to the ones that don’t fit the rule?', ['Thompson, K. (1968). Regular Expression Search Algorithm. Communications of the ACM, 11(6).']),
  S('I-21', false, 'cambridge', ['Karen Spärck Jones', 'Inverse document frequency', '1972', 'University of Cambridge'], [],
    ['Karen Spärck Jones worked on how a computer should find documents.', 'Her 1972 paper says that a word found in few documents tells you more than a word found in most.', 'That weight was later named inverse document frequency, and it went into nearly every search engine.'],
    ['She wanted a simple, statistical reason to prefer some matching words over others.', 'Counting words alone lets “the” and “of” outvote everything.', 'Search engines still combine how often a word appears with how rare it is.'],
    ['Tokenization', 'Stemming and lemmatization', 'n-grams', 'Bag of words', 'TF-IDF', 'Cosine and Jaccard similarity'],
    (C) => `Her rule runs the opposite way to Marginalia’s. For her, what is rare carries the information. For Marginalia, what is rare is dropped first.`, [[5, 1]], 'engineer',
    'Which word would find your favourite book fastest: “the”, or its oddest word?', 'Why do rare words matter more?', ['Spärck Jones, K. (1972). A statistical interpretation of term specificity and its application in retrieval. Journal of Documentation, 28(1).']),
  S('I-22', false, 'london', ['David Cox', 'Regression for binary outcomes', '1958', 'Birkbeck College, London'], [],
    ['Some outcomes are yes or no: returned late or not, borrowed or not.', 'David Cox, then at Birkbeck, set out in 1958 how to model the chance of a yes with an S-shaped curve.', 'The curve never goes below 0 or above 1, which a straight line cannot promise.'],
    ['He wanted regression for outcomes that are not amounts.', 'A model is surest about what it has seen most, and silent about what it has never seen.', 'It is the workhorse classifier of medicine, credit and advertising.'],
    ['Logistic regression', 'The sigmoid', 'Log-odds', 'Cross-entropy', 'Reading coefficients', 'Generative and discriminative classifiers'],
    (C) => `Last month Marginalia showed ${n(C.shown.titlesShown)} different titles to everyone put together. Each was borrowed ${n(C.shown.loansPerShown)} times on average. A title that was not shown averaged ${C.shown.loansPerUnshown.toFixed(2)}. A model trained on that calls the first kind near-certain and the second near-impossible.`, [[5, 1]], 'model',
    'What is the chance it rains tomorrow? Can a chance be more than 100%?', 'Why is the curve bent and not straight?', ['Cox, D. R. (1958). The regression analysis of binary sequences. Journal of the Royal Statistical Society B, 20(2).']),
  S('I-23', true, 'london', ['Mervyn Stone', 'Cross-validation', '1974', 'University College London'], [],
    ['A model always looks good on the data it was fitted to.', 'Mervyn Stone’s 1974 paper made a practice precise: hold some data back, fit on the rest, score on what was held back, and rotate.', 'The score on unseen data is the one that counts.'],
    ['He wanted an honest estimate of how a model would do on new cases.', 'If the held-back data share something with the training data, the test is too easy.', 'Every machine learning result you read was, or should have been, scored this way.'],
    ['Training, validation and test sets', 'k-fold and leave-one-out', 'Stratified and time-series validation', 'Bias and variance', 'Over- and underfitting'],
    (C) => `When Marginalia 2 was approved, a “top five for your department” model was scored on shuffled months of year three and got ${p(C.validation.shuffled, 1)}. Scored forward, on year four, the same model gets ${p(C.validation.forward, 1)}. Year three had shared reading lists in six departments. They ended.`, [[4, -1], [1, 1]], 'evaluate',
    'If you practise a quiz with the answer sheet open, what does your score tell you?', 'Why is it cheating to test on what you studied?', ['Stone, M. (1974). Cross-validatory choice and assessment of statistical predictions. Journal of the Royal Statistical Society B, 36(2).']),
  S('I-24', true, 'cranfield', ['Cyril Cleverdon', 'The Cranfield tests', '1957 to 1967', 'the College of Aeronautics, Cranfield'], [],
    ['Cyril Cleverdon was the librarian of the College of Aeronautics at Cranfield.', 'From 1957 he ran experiments to settle an argument: which way of indexing documents finds the right ones?', 'He fixed a set of documents, a set of questions and a list of right answers, then scored each system on precision and recall.'],
    ['He wanted evidence in a debate that had been run on opinion.', 'When what you seek is rare, a system can be “accurate” by never finding it.', 'Search engines and classifiers are still tested on a fixed collection with known answers.'],
    ['Confusion matrix', 'Accuracy, precision, recall and specificity', 'F1', 'When accuracy misleads'],
    (C) => `Scored on last year’s log, a rule that shows everyone the same five most-borrowed titles gets ${p(C.baseline.topFive)}. Marginalia itself scored ${p(C.baseline.firstYear)} in its first year. The rule offers 5 titles out of ${n(C.meta.titles)}.`, [[4, -2]], 'evaluate',
    'A smoke alarm that never rings is right almost every day. Is it a good alarm?', 'How can something be mostly right and still useless?', ['Cleverdon, C. W. (1967). The Cranfield tests on index language devices. Aslib Proceedings, 19(6).']),
  S('I-25', true, 'monash', ['Fei Tony Liu, Kai Ming Ting and Zhi-Hua Zhou', 'Isolation Forest', '2008', 'Monash University'], [],
    ['Most detectors describe what is normal and flag whatever does not fit.', 'Fei Tony Liu, Kai Ming Ting and Zhi-Hua Zhou went the other way in 2008. Odd points are few and different, so they are easy to cut off from the rest.', 'Slice the data at random. The points left alone after very few cuts are the suspects.'],
    ['They wanted a detector that was fast on large data and needed no picture of “normal”.', 'An outlier may be an error, or it may be the most interesting case you have.', 'It is a standard first check for fraud, faults and bad sensor readings.'],
    ['Types and causes of outliers', 'Outlier and novelty', 'Isolation forest', 'Other detectors'],
    (C) => `Before training, a cleaning step dropped the ${p(C.planted.cleanedShare)} most unusual readers: ${C.cleaning.readers} people. ${p(C.cleaning.rareShareDropped)} of what they borrowed was from rare subjects. For everyone else it was ${p(C.cleaning.rareShareOthers)}.`, [[5, 1]], 'clean',
    'Who is the “outlier” in your street: the tallest, the oldest, the one with a parrot? Is that a mistake?', 'Is being unusual the same as being wrong?', ['Liu, F. T., Ting, K. M., & Zhou, Z.-H. (2008). Isolation Forest. IEEE International Conference on Data Mining.']),
];

export const PART2 = [
  S('II-1', false, 'nvidia', ['Ian Buck and colleagues', 'CUDA', '2007', 'Nvidia'], [],
    ['Graphics cards were built to do the same small sum on millions of pixels at once.', 'Ian Buck had shown at Stanford that the same hardware could do general arithmetic. At Nvidia he led CUDA, released in 2007, which let programmers use it directly.', 'Multiplying large tables of numbers is exactly the sum that machine learning needs.'],
    ['They wanted scientists to use a graphics card without pretending their problem was a picture.', 'A table that is nearly all blanks wastes most of the arithmetic.', 'Nearly every neural network is trained on hardware like this.'],
    ['Vectors and matrices', 'Multiplication and transpose', 'Determinant, inverse and rank', 'Eigenvectors and eigenvalues', 'Jacobian and Hessian in brief'],
    (C) => `The grid of readers by titles is ${p(C.sparsity.empty, 1)} empty. A blank means “did not borrow”. It does not say “did not want” or “was never offered”.`, [], 'engineer',
    'Stretch a rubber band with a picture on it. Which lines stay pointing the same way?', 'What does an empty box in a table mean?', ['Nickolls, J., Buck, I., Garland, M., & Skadron, K. (2008). Scalable Parallel Programming with CUDA. ACM Queue, 6(2).']),
  S('II-2', true, 'unc', ['Herbert Robbins and Sutton Monro', 'Stochastic approximation', '1951', 'University of North Carolina'], [],
    ['In 1847 Augustin-Louis Cauchy described finding a low point by stepping downhill again and again.', 'In 1951 Herbert Robbins and Sutton Monro, at Chapel Hill, showed you still arrive when each reading of the slope is noisy, as long as the steps shrink at the right rate.', 'Training a neural network is this idea repeated a very large number of times.'],
    ['They wanted to find a target setting from noisy measurements, one at a time.', 'Steps too large overshoot. Steps too small never arrive. Some valleys have more than one floor.', 'Every modern optimizer is a refinement of stepping downhill on noisy slopes.'],
    ['Cost functions', 'Gradient descent and learning rate', 'Convex and non-convex surfaces', 'Batch, stochastic and mini-batch descent', 'Feature normalization'],
    (C) => `Marginalia is retrained every month on that month’s loans. Each month the lowest point of its loss moves a little toward what it already shows, and it follows.`, [[5, 1]], 'model',
    'Walk downstairs with your eyes shut. How do you know when you are at the bottom?', 'What if there is a deeper valley you never find?', ['Robbins, H., & Monro, S. (1951). A Stochastic Approximation Method. The Annals of Mathematical Statistics, 22(3).']),
  S('II-3', true, 'stanford', ['Trevor Hastie and Robert Tibshirani', 'The lasso, and The Elements of Statistical Learning', '1996 and 2001', 'Stanford University'], ['Jerome Friedman'],
    ['A model with many inputs can fit noise.', 'Robert Tibshirani’s 1996 lasso gives the model a budget for the total size of its coefficients. With a tight budget, some are set to exactly zero.', 'With Trevor Hastie and Jerome Friedman he later wrote the textbook that many people learn this from.'],
    ['He wanted a model that picks its own short list of inputs.', 'The inputs that go to zero first are the ones with little data behind them.', 'It is a standard tool whenever there are more inputs than a person can inspect.'],
    ['Overfitting and Occam’s razor', 'Ridge, lasso and elastic net', 'Choosing lambda', 'Softmax and multinomial logit'],
    (C) => `A lasso that predicts how closely a reader follows the screen kept ${C.lasso.kept} of ${C.lasso.total} subject features: ${C.lasso.names.join(', ')}. Of the ${C.lasso.rareTotal} rare subjects it kept ${C.lasso.rareKept}.`, [[5, 1]], 'model',
    'Pack for a trip with a small bag. What gets left behind first?', 'Is a simpler answer always a better one?', ['Tibshirani, R. (1996). Regression Shrinkage and Selection via the Lasso. Journal of the Royal Statistical Society B, 58(1).', 'Hastie, T., Tibshirani, R., & Friedman, J. (2001). The Elements of Statistical Learning. Springer.']),
  S('II-4', true, 'harvard', ['Arthur Dempster, Nan Laird and Donald Rubin', 'The EM algorithm', '1977', 'Harvard University'], [],
    ['Suppose the data come from two overlapping groups and nobody recorded which.', 'Arthur Dempster, Nan Laird and Donald Rubin, at Harvard in 1977, gave a general recipe: guess the missing labels softly, refit, and repeat.', 'Each round can only make the fit better or leave it the same.'],
    ['They saw that many separate tricks for incomplete data were one method.', 'It climbs to the nearest peak, which need not be the highest.', 'It fits mixtures, fills gaps and trains models with hidden parts.'],
    ['The Gaussian and multivariate Gaussian', 'The covariance matrix', 'Soft k-means', 'Gaussian mixtures', 'Expectation-maximization'],
    (C) => `One year-one reader is ${C.mix.map((m) => p(m[1]) + ' ' + m[0]).join(', ')}. A hard cluster filed that reader under ${C.mix[0][0]} and served nothing else.`, [[5, 1]], 'model',
    'Are you one kind of reader, or a mixture? What are your shares?', 'Why must everyone go in exactly one box?', ['Dempster, A. P., Laird, N. M., & Rubin, D. B. (1977). Maximum Likelihood from Incomplete Data via the EM Algorithm. Journal of the Royal Statistical Society B, 39(1).']),
  S('II-5', false, 'columbia', ['Harold Hotelling', 'Principal components', '1933', 'Columbia University'], [],
    ['Scores on many tests tend to move together. How many separate things are really being measured?', 'Harold Hotelling, at Columbia in 1933, showed how to find the few directions along which the data vary most. The geometry had been worked out in 1901.', 'Keep the first few directions and you keep most of the picture.'],
    ['He wanted to replace many correlated measurements with a few independent ones.', '“Most of the variation” is, by construction, what most cases have in common.', 'It is the first thing tried when data have too many columns to look at.'],
    ['The curse of dimensionality', 'PCA', 'Eigenvectors of the covariance matrix', 'Variance explained'],
    (C) => `Marginalia keeps ${C.pca.components} components of taste, which hold ${p(C.pca.explained)} of the variation. They keep ${p(C.pca.commonKept)} of what varies in common subjects and ${p(C.pca.rareKept)} in rare ones.`, [[5, 1]], 'engineer',
    'Hold a toy up to a lamp. Which way round gives the most recognisable shadow?', 'What is lost in a shadow?', ['Hotelling, H. (1933). Analysis of a complex of statistical variables into principal components. Journal of Educational Psychology, 24.']),
  S('II-6', false, 'belllabs', ['Corinna Cortes and Vladimir Vapnik', 'Support-vector networks', '1995', 'AT&T Bell Laboratories'], [],
    ['Many lines can separate two groups of points. Which is best?', 'Corinna Cortes and Vladimir Vapnik, at Bell Labs in 1995, chose the one with the widest empty margin on both sides, and let a few points fall on the wrong side at a cost.', 'Only the points on the edge of the margin matter. They are called support vectors.'],
    ['They wanted a classifier whose ability to generalize could be argued from theory.', 'A boundary is only drawn between the examples it was given.', 'For years it was the method to beat on small and medium data.'],
    ['Maximum margin', 'Support vectors', 'Soft margin', 'Multi-class', 'The kernel trick'],
    (C) => `Marginalia’s examples of “borrowed” are nearly all books it had shown. A boundary drawn from those examples puts every unseen book on the “no” side.`, [[5, 1]], 'model',
    'Draw a line between cats and dogs on paper. Where do you put a fox?', 'What happens to things the line has never met?', ['Cortes, C., & Vapnik, V. (1995). Support-Vector Networks. Machine Learning, 20(3).']),
  S('II-7', true, 'berkeley', ['Leo Breiman', 'Classification and regression trees, bagging and random forests', '1984, 1996, 2001', 'UC Berkeley'], [],
    ['Leo Breiman left a professorship to work as a consultant, and came back to Berkeley convinced that statistics should be judged by how well it predicts.', 'With three colleagues he published a method for growing decision trees in 1984.', 'One tree is jumpy. In 1996 and 2001 he showed that many trees, each grown on a slightly different sample, vote their way to a steadier answer.'],
    ['He wanted models that people could read, and then models that simply worked.', 'A tree grown to the end memorizes its data. Pruned hard, it forgets the small cases.', 'Forests and their boosted cousins still win on tables of data.'],
    ['Entropy, information gain and the Gini index', 'Hunt’s algorithm', 'Early stopping and pruning', 'Regression trees', 'Random forests and boosting'],
    (C) => `A tree that predicts which titles reach Marginalia’s shortlist asks one question first: was it borrowed more than ${C.tree.threshold} times last year? ${n(C.tree.above)} titles were. By the storage rule, a title with fewer than ${C.meta.storageBelow ?? 2} loans in a year goes off-site.`, [[2, 1], [5, 1]], 'model',
    'Play twenty questions. Which first question splits the possibilities best?', 'What happens to the small leaves when you prune?', ['Breiman, L., Friedman, J., Olshen, R., & Stone, C. (1984). Classification and Regression Trees. Wadsworth.', 'Breiman, L. (2001). Random Forests. Machine Learning, 45(1).']),
  S('II-8', false, 'microsoft', ['Jamie Shotton, Andrew Fitzgibbon, Andrew Blake and colleagues', 'Body-part recognition for Kinect', '2011', 'recorded at Microsoft Research Cambridge'], [],
    ['A depth camera measures how far away each pixel is. Which pixels are a hand?', 'Jamie Shotton, Andrew Fitzgibbon, Andrew Blake and colleagues trained forests of decision trees to label every pixel with a body part, using simple comparisons of depth at two nearby points.', 'They trained on a huge set of computer-drawn bodies, because nobody could label that many real ones.'],
    ['They needed body tracking fast enough for a games console.', 'A pose unlike anything in the training set gets a confident wrong answer.', 'Simple tests, many trees and a vote remain a fast recipe for vision on small devices.'],
    ['Decision forests in use'],
    (C) => `A forest is only as broad as the examples it was given. Marginalia’s examples came from its own screens.`, [], 'model',
    'Could you learn what a giraffe is from drawings alone?', 'What if it sees a pose nobody drew?', ['Shotton, J., et al. (2011). Real-Time Human Pose Recognition in Parts from Single Depth Images. CVPR.']),
  S('II-9', true, 'netflix', ['Robert Bell, Yehuda Koren, Chris Volinsky and the team BellKor’s Pragmatic Chaos', 'The Netflix Prize', '2009', 'Netflix'], [],
    ['In 2006 Netflix offered a million dollars to anyone who could predict film ratings 10% better than its own system.', 'It took nearly three years. The winning entry in 2009 was a blend of hundreds of models from three teams that had merged.', 'A second team reached the same score about twenty minutes later.'],
    ['Thousands of teams wanted the lowest error on a hidden set of ratings.', 'Netflix later wrote that it never put the full winning blend into service: the gain did not justify the engineering.', 'Blending models, and factoring a ratings table into hidden tastes, both became standard.'],
    ['Voting, averaging, stacking and blending', 'Matrix factorization'],
    (C) => `A blend can win on the score and still answer the wrong question. The board’s score, the hit rate, rose every year: ${C.y.hit.map((h) => p(h)).join(', ')}.`, [[4, -1]], 'model',
    'Ask three people to guess the number of sweets in a jar. Is the average better than each guess?', 'If you win the game, did you solve the problem?', ['Koren, Y., Bell, R., & Volinsky, C. (2009). Matrix Factorization Techniques for Recommender Systems. Computer, 42(8).']),
  S('II-10', true, 'google', ['Rajeev Motwani and Terry Winograd', 'PageRank', '1998', 'recorded at Stanford University'], ['Lawrence Page', 'Sergey Brin'],
    ['Which web page matters most? Counting the links to it is easy to cheat.', 'The PageRank report of 1998, written at Stanford by Lawrence Page, Sergey Brin, Rajeev Motwani and Terry Winograd, imagines a reader who follows links at random for ever.', 'A page matters if that reader lands on it often, which happens when pages that matter link to it.'],
    ['They wanted a measure of importance that came from the structure of the web itself.', 'Rank flows to what is already well linked, so the well known become better known.', 'Random walks on graphs rank pages, papers, players and proteins.'],
    ['Graphs, adjacency matrix and edge list', 'Degree, closeness and betweenness centrality', 'Degree distributions'],
    (C) => `Link each title to the one the same reader borrowed next. A random walk over last year’s ${n(C.pagerank.nodes)} titles spends ${p(C.pagerank.top100)} of its time on the same hundred.`, [[5, 1]], 'model',
    'Who in your class or family is “most connected”? Is that the same as most liked?', 'Why do the famous get more famous?', ['Page, L., Brin, S., Motwani, R., & Winograd, T. (1999). The PageRank Citation Ranking: Bringing Order to the Web. Stanford InfoLab.']),
  S('II-11', true, 'santafe', ['Michelle Girvan and Mark Newman', 'Community structure in networks', '2002', 'the Santa Fe Institute'], [],
    ['Michelle Girvan and Mark Newman asked how to find the groups inside a network without being told how many there are.', 'Their 2002 method looks for the links that the most shortest paths run across. Those are the bridges between groups. Cut them and the groups fall apart.', 'Newman and Girvan later added a score, modularity, for how good a split is.'],
    ['They wanted the communities that the network itself implies.', 'A network where everyone is linked to everyone has no communities to find.', 'Community detection maps friendships, food webs and fields of science.'],
    ['Layouts', 'Density, clustering coefficient and assortativity', 'Hierarchical clustering', 'Modularity', 'Ratio and normalized cuts', 'Block models'],
    (C) => `Link two readers when they share enough of their reading. In year one the graph had clear communities: modularity ${C.rgraph.first.modularity.toFixed(2)}, with ${p(C.rgraph.first.density)} of possible links present. In year six ${p(C.rgraph.last.density)} of links are present and modularity is ${C.rgraph.last.modularity.toFixed(2)}. Everyone is reading the same few books.`, [[1, -1], [5, 1]], 'describe',
    'Draw your family and friends as dots and lines. Where are the bridges?', 'If everybody knows everybody, are there still groups?', ['Girvan, M., & Newman, M. E. J. (2002). Community structure in social and biological networks. PNAS, 99(12).']),
  S('II-12', false, 'cornell', ['Frank Rosenblatt', 'The perceptron', '1958', 'recorded at Cornell University'], [],
    ['Frank Rosenblatt, a psychologist at the Cornell Aeronautical Laboratory, described a machine in 1958 that learns from examples.', 'It adds up its inputs, each multiplied by a weight, and says yes if the total passes a threshold. When it is wrong, it nudges the weights.', 'In 1969 a book called Perceptrons showed what a single layer cannot learn, and interest cooled for years.'],
    ['He wanted a machine that could learn to recognise patterns the way he thought a brain might.', 'One layer draws one straight line. Some patterns need two.', 'Every unit in a modern network is a descendant of this one.'],
    ['Perceptron', 'Weights and bias', 'Activation functions', 'What one line can separate'],
    (C) => `One line can say “popular or not”. It cannot say “loved by a few”, because those books are scattered on both sides of any line through loan counts.`, [], 'model',
    'Can you sort your shoes into “mine” and “not mine” with one rule? Into “left” and “right”?', 'Why can’t one line do everything?', ['Rosenblatt, F. (1958). The Perceptron: A Probabilistic Model for Information Storage and Organization in the Brain. Psychological Review, 65(6).']),
  S('II-13', true, 'ucsd', ['David Rumelhart, Geoffrey Hinton and Ronald Williams', 'Back-propagation', '1986', 'UC San Diego'], [],
    ['A network with hidden layers can learn what one layer cannot. But when the answer is wrong, which of a thousand weights is to blame?', 'David Rumelhart, Geoffrey Hinton and Ronald Williams showed in 1986 how to pass the error backward, layer by layer, giving each weight its share.', 'Others had worked out the mathematics earlier. This paper showed that it made networks learn useful things.'],
    ['They wanted hidden layers to find their own useful features.', 'Passed back through many layers, the blame can shrink to nothing or blow up.', 'Every neural network in this game, and outside it, is trained this way.'],
    ['Multilayer networks', 'The forward pass', 'Loss functions', 'Back-propagation', 'Vanishing and exploding gradients', 'Hyperparameters'],
    (C) => `The error signal flows back only from books that were on a screen. Last month that was ${n(C.shown.titlesShown)} titles of ${n(C.meta.titles)}. The rest sent back nothing to learn from.`, [[5, 1]], 'model',
    'A cake comes out wrong. Was it the oven, the eggs or the recipe? How would you find out?', 'What if nobody ever tells you that you were wrong?', ['Rumelhart, D. E., Hinton, G. E., & Williams, R. J. (1986). Learning representations by back-propagating errors. Nature, 323.']),
  S('II-14', false, 'belllabs', ['Yann LeCun and Léon Bottou', 'Convolutional networks', '1989 to 1998', 'AT&T Bell Laboratories'], ['Yoshua Bengio', 'Patrick Haffner'],
    ['Yann LeCun’s group at Bell Labs taught a network to read handwritten postal codes in 1989.', 'Its first layers slide a small window across the picture, looking for the same little shapes everywhere.', 'By the late 1990s a version was reading the amounts on a good share of the cheques written in the United States.'],
    ['They wanted a network that would still know a digit if it moved a little or was written larger.', 'It reads what it was trained on. Unusual handwriting comes out as a confident mistake.', 'Sliding windows are the basis of most machine vision.'],
    ['Convolution', 'Feature maps', 'Pooling', 'Convolutional network hyperparameters'],
    (C) => `About ${n(C.planted.handCards)} handwritten catalogue cards were never read by machine. Those books have no record in the system, so they cannot be suggested at all.`, [[3, 1]], 'engineer',
    'Slide a cardboard tube over a page. What can you tell from one small circle at a time?', 'What happens to the books with messy cards?', ['LeCun, Y., Bottou, L., Bengio, Y., & Haffner, P. (1998). Gradient-based learning applied to document recognition. Proceedings of the IEEE, 86(11).']),
  S('II-15', false, 'toronto', ['Geoffrey Hinton and Ruslan Salakhutdinov', 'Deep autoencoders', '2006', 'University of Toronto'], [],
    ['Squeeze a picture through a narrow middle layer and ask the network to rebuild it on the other side.', 'Geoffrey Hinton and Ruslan Salakhutdinov showed in 2006 how to train such a network when it is many layers deep, by preparing one layer at a time.', 'What gets through the narrow part is a compact code for the picture.'],
    ['They wanted a better way than principal components to shrink data.', 'The code keeps what is common across pictures. The odd detail is the first thing lost.', 'Compact learned codes sit inside search, recommendation and image generation.'],
    ['Undercomplete, sparse and denoising autoencoders', 'Autoencoders and PCA'],
    (C) => `Marginalia stores each reader as ${C.planted.profile} numbers. What those numbers cannot rebuild is the unusual loans.`, [[5, 1]], 'engineer',
    'Describe your day in five words. What did you leave out?', 'Why is it the strange things that go missing?', ['Hinton, G. E., & Salakhutdinov, R. R. (2006). Reducing the Dimensionality of Data with Neural Networks. Science, 313.']),
];
